# ── Main client ──────────────────────────────────────────────────────────────


class OpenAIClient:
    """A lightweight client for OpenAI'"'s Responses API.

    Uses only the Python standard library (no "'``openai``, no ``requests``).
    """

    def __init__(self, config: Optional[OpenAIClientConfig] = None) -> None:
        self.config = config or OpenAIClientConfig()

    # ── Public API ───────────────────────────────────────────────────────────

    def send_prompt(
        self,
        prompt: str,
        *,
        model: Optional[str] = None,
        temperature: Optional[float] = None,
        max_output_tokens: Optional[int] = None,
        top_p: Optional[float] = None,
        stream_callback: None  # actually Optional[Callable[[str], None]]
        | None = None,
    ) -> str:
        """Send a text prompt and return the assistant'"'s reply.

        When *stream_callback* is provided, each text delta is delivered to
        the callable as it arrives.  The full reply is still returned once
        streaming completes.
        \"\"\"
        body = self._build_body(
            prompt=prompt,
            model=model,
            temperature=temperature,
            max_output_tokens=max_output_tokens,
            top_p=top_p,
            stream=stream_callback is not None,
        )

        if stream_callback is not None:
            return self._stream(body, stream_callback)
        return self._send(body)

    # ── Request helpers ──────────────────────────────────────────────────────

    def _build_body(
        self,
        prompt: str,
        model: Optional[str],
        temperature: Optional[float],
        max_output_tokens: Optional[int],
        top_p: Optional[float],
        stream: bool,
    ) -> dict:
        body: dict[str, object] = {
            \"model\": model or self.config.model,
            \"input\": prompt,
        }
        if stream:
            body[\"stream\"] = True

        temp = temperature if temperature is not None else self.config.temperature
        if temp is not None:
            body[\"temperature\"] = temp

        mot = (
            max_output_tokens
            if max_output_tokens is not None
            else self.config.max_output_tokens
        )
        if mot is not None:
            body[\"max_output_tokens\"] = mot

        tp = top_p if top_p is not None else self.config.top_p
        if tp is not None:
            body[\"top_p\"] = tp

        return body

    def _build_headers(self) -> dict[str, str]:
        key = self.config.api_key
        if not key:
            raise AuthenticationError(
                \"No API key provided.  Set the OPENAI_API_KEY environment \"
                \"variable or pass api_key to OpenAIClientConfig.\"
            )
        return {
            \"Authorization\": f\"Bearer {key}\",
            \"Content-Type\": \"application/json\",
        }

    def _request(
        self, headers: dict[str, str], data: bytes, stream: bool = False
    ) -> urllib.request.OpenerDirector:
        req = urllib.request.Request(
            self.config.base_url,
            data=data,
            headers=headers,
            method=\"POST\",
        )
        ctx = ssl.create_default_context()
        return urllib.request.urlopen(
            req, timeout=self.config.request_timeout, context=ctx
        )

    # ── Non‑streaming ────────────────────────────────────────────────────────

    def _send(self, body: dict) -> str:
        headers = self._build_headers()
        data = json.dumps(body).encode(\"utf-8\")

        try:
            resp = self._request(headers, data, stream=False)
        except urllib.error.HTTPError as exc:
            self._raise_by_status(exc)

        raw = resp.read()
        payload = json.loads(raw)
        self._check_api_error(payload)
        return self._extract_text(payload)

    # ── Streaming (SSE) ──────────────────────────────────────────────────────

    def _stream(self, body: dict, callback) -> str:  # type: ignore[type-arg]
        headers = self._build_headers()
        data = json.dumps(body).encode(\"utf-8\")
        collected: list[str] = []

        try:
            resp = self._request(headers, data, stream=True)
        except urllib.error.HTTPError as exc:
            self._raise_by_status(exc)

        buffer = \"\"
        for chunk in iter(lambda: resp.read(4096), b\"\"):
            buffer += chunk.decode(\"utf-8\")
            # SSE protocol: lines starting with \"data: \"
            while \"\\n\" in buffer:
                line, buffer = buffer.split(\"\\n\", 1)
                line = line.strip()
                if not line:
                    continue
                if line.startswith(\"data: \"):
                    payload_str = line[6:]
                elif line == \"data: [DONE]\":
                    continue
                else:
                    # Some events may come without \"data: \" prefix
                    payload_str = line

                if payload_str == \"[DONE]\":
                    continue

                try:
                    event = json.loads(payload_str)
                except json.JSONDecodeError:
                    continue

                delta = self._extract_stream_delta(event)
                if delta:
                    callback(delta)
                    collected.append(delta)

        return \"\".join(collected)

    # ── Response extraction ──────────────────────────────────────────────────

    @staticmethod
    def _extract_text(payload: dict) -> str:
        \"\"\"Extract the assistant's reply text from a non‑streaming response.\"\"\"
        try:
            output = payload[\"output\"]
            for item in output:
                if item.get(\"type\") == \"message\" and item.get(\"role\") == \"assistant\":
                    content = item.get(\"content\", [])
                    for block in content:
                        if block.get(\"type\") in (\"output_text\", \"text\"):
                            return block.get(\"text\", \"\")
                    # Fallback: join all text blocks
                    parts = [
                        b.get(\"text\", \"\")
                        for b in content
                        if b.get(\"type\") in (\"output_text\", \"text\")
                    ]
                    if parts:
                        return \"\".join(parts)
        except (KeyError, IndexError, TypeError):
            pass
        return payload.get(\"text\", \"\")

    @staticmethod
    def _extract_stream_delta(event: dict) -> str:
        \"\"\"Extract the text delta from a single SSE event.\"\"\"
        event_type = event.get(\"type\", \"\")

        if event_type == \"response.output_text.delta\":
            return event.get(\"delta\", \"\")

        if event_type == \"response.output_text.done\":
            return event.get(\"text\", \"\")

        # Older event shape; be defensive.
        delta = event.get(\"delta\", \"\")
        if isinstance(delta, str) and delta:
            return delta

        return \"\"

    # ── Error handling ───────────────────────────────────────────────────────

    @staticmethod
    def _check_api_error(payload: dict) -> None:
        err = payload.get(\"error\")
        if err:
            msg = err.get(\"message\", str(err))
            typ = err.get(\"type\", \"\")
            if typ == \"insufficient_quota\":
                raise RateLimitError(msg)
            if typ == \"authentication_error\":
                raise AuthenticationError(msg)
            raise APIError(msg)

    @staticmethod
    def _raise_by_status(exc: urllib.error.HTTPError) -> None:
        status = exc.code
        try:
            detail = exc.read().decode(\"utf-8\")
        except Exception:
            detail = str(exc)
        try:
            detail_obj = json.loads(detail)
            msg = detail_obj.get(\"error\", {}).get(\"message\", detail)
        except (json.JSONDecodeError, AttributeError, KeyError):
            msg = detail

