        "--temperature",
        type=float,
        default=None,
        help="Sampling temperature (0‑2).",
    )
    parser.add_argument(
        "--max-tokens",
        type=int,
        default=None,
        help="Maximum output tokens.",
    )
    args = parser.parse_args()

